mapper.select:
SELECT *
FROM calendar_day
WHERE tenant_id = #{tenantId}
  AND calendar_id = #{calendarId}
  AND calendar_date = #{date}
LIMIT 1

SELECT *
FROM calendar_day
WHERE tenant_id = #{tenantId}
  AND calendar_id = #{calendarId}
  AND calendar_date BETWEEN #{startDate} AND #{endDate}
ORDER BY calendar_date

SELECT *
FROM calendar_day
WHERE tenant_id = #{tenantId}
  AND calendar_id = #{calendarId}
  AND calendar_year = #{year}
ORDER BY calendar_date

SELECT COUNT(1)
FROM calendar_day
WHERE tenant_id = #{tenantId}
  AND calendar_id = #{calendarId}
  AND calendar_year = #{year}

SELECT COUNT(1)
FROM calendar_day
WHERE tenant_id = #{tenantId}
  AND calendar_id = #{calendarId}
  AND calendar_year = #{year}
  AND enabled = 1
